    function rocsolver_sorgqr(handle, m, n, k, A, lda, ipiv) &
       result(sorgqr) &
       bind(C, name="rocsolver_sorgqr")
       import :: c_ptr, c_int, c_float
       type(c_ptr), value :: handle
