    function rocsolver_dbdsvdx(handle, uplo, svect, srange, n, D, E, vl, vu, il, iu, nsv, S, Z, &
                               ldz, ifail, info) &
       result(dbdsvdx) &
       bind(C, name="rocsolver_dbdsvdx")
       import :: c_ptr, c_int, c_double
