       real(c_double), value :: vl
       real(c_double), value :: vu
       integer(c_int), value :: il
       integer(c_int), value :: iu
       integer(c_int) :: nsv(*)
       real(c_double) :: S(*)
       real(c_double) :: Z(*)
       integer(c_int), value :: ldz
       integer(c_int) :: ifail(*)
       integer(c_int) :: info(*)
       integer(c_int) :: dbdsvdx
    end function rocsolver_dbdsvdx

    !---------------------------------------------
    ! rocsolver_sgetf2_npvt
    !---------------------------------------------
    !> \brief The GETF2_NPVT functions compute the LU factorization of a general ``m``-by-``n``
    !> matrix ``A``
    !> without partial pivoting.
    !>
    !> \details
    !> (This is the unblocked Level-2-BLAS version of the algorithm. An optimized internal
    !> implementation without rocBLAS calls
    !> could be executed with small and mid-size matrices if optimizations are enabled (default
    !> option). For more details, see the
    !> "rocSOLVER performance tuning" guide.)
    !>
    !> The factorization has the form
    !>
    !> \f[
    !> A = LU
    !> \f]
    !>
    !> where L is lower triangular with unit
    !> diagonal elements (lower trapezoidal if ``m`` > ``n``), and U is upper
    !> triangular (upper trapezoidal if ``m`` < ``n``).
    !>
    !> \note
    !> Although this routine can offer better performance, Gaussian elimination without pivoting is
    !> not backward stable.
    !> If numerical accuracy is compromised, use the legacy-LAPACK API \ref rocsolver_sgetf2 "GETF2"
    !> routines instead.
    !>
    !> @param[in]
    !> handle      rocblas_handle.
    !> @param[in]
    !> m           rocblas_int. m >= 0.
    !> The number of rows of the matrix A.
    !> @param[in]
    !> n           rocblas_int. n >= 0.
    !> The number of columns of the matrix A.
    !> @param[inout]
    !> A           pointer to type. Array on the GPU of dimension lda*n.
    !> On entry, the m-by-n matrix A to be factored.
    !> On exit, the factors L and U from the factorization.
    !> The unit diagonal elements of L are not stored.
    !> @param[in]
    !> lda         rocblas_int. lda >= m.
    !> Specifies the leading dimension of A.
    !> @param[out]
    !> info        pointer to a rocblas_int on the GPU.
    !> If info = 0, successful exit.
    !> If info = i > 0, U is singular. U[i,i] is the first zero element in the diagonal. The
    !> factorization from
    !> this point might be incomplete.
    function rocsolver_sgetf2_npvt(handle, m, n, A, lda, info) &
       result(sgetf2_npvt) &
       bind(C, name="rocsolver_sgetf2_npvt")
       import :: c_ptr, c_int, c_float
       type(c_ptr), value :: handle
       integer(c_int), value :: m
       integer(c_int), value :: n
       real(c_float) :: A(*)
       integer(c_int), value :: lda
       integer(c_int) :: info(*)
       integer(c_int) :: sgetf2_npvt
    end function rocsolver_sgetf2_npvt

    !---------------------------------------------
    ! rocsolver_dgetf2_npvt
