    function rocsolver_chegs2(handle, itype, uplo, n, A, lda, B, ldb) &
       result(chegs2) &
       bind(C, name="rocsolver_chegs2")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: itype
       integer(c_int), value :: uplo
       integer(c_int), value :: n
       type(c_ptr), value :: A
