    function rocsolver_scsrrf_refactlu(handle, n, nnzA, ptrA, indA, valA, nnzT, ptrT, indT, valT, &
                                       pivP, pivQ, rfinfo) &
       result(scsrrf_refactlu) &
       bind(C, name="rocsolver_scsrrf_refactlu")
       import :: c_ptr, c_int, c_float
